    for (const s of J('Gameplay/supports.json').supports) supports[s.Id.toLowerCase()] = pick(s, ['Id', 'Name', 'Description', 'RequiresAnyTag', 'ExcludeTags', 'Mods', 'ManaMultiplier', 'Attribute']);
    // Attribute sets the gem's colour in game (supports.json Color, checked 4 Nov 2026: all 17 Str are red,
    // 25 Dex green, 28 Int purple). The page only uses it for the colour marker next to the name.

    const tree = J('Gameplay/passive_tree.json');
    const nodes = {};
    for (const n of tree.nodes) nodes[n.Id] = pick(n, ['Id', 'Name', 'Kind', 'Mods', 'Text', 'Region', 'X', 'Y', 'Links', 'ClassStart', 'Price', 'Choice', 'Group', 'Fp']); // Fp: the save's PassiveFp per node (the Creator tab writes it, as tools/offline-clone.js does)

