  // One edit in an item box. ch is anything holding items (a character, or the Item Compare tab's own item);
  // done() after a change, render() to redraw only.
  function gearChange(ch, t, k, done, render) {
    const done0 = done; done = (...a) => { const m = fixHands(ch); if (m) status = m; return done0(...a); };
    const f = t.dataset.f, v = t.value;
    const { it, slot, key } = itemOf(ch, t); if (!slot) return;
    k.openItems.add(String(key));
    if (f === 'uniqmode') {
      if (t.checked) {
        k.oathwordMode.delete(String(key)); k.oathwordSelection.delete(String(key));
        if (oathwordForItem(it, slot)) it.runes = [];
        k.uniqueMode.add(String(key));
      } else {
        k.uniqueMode.delete(String(key));
        if (it && it.rarity === 'Unique') Object.assign(it, { rarity: 'Rare', unique: 'None', name: '', affixes: [], roll: undefined });
      }
      return it ? done() : render();
    }
    if (f === 'oathmode') {
      if (t.checked) {
        k.uniqueMode.delete(String(key)); k.oathwordMode.add(String(key));
        if (it && it.rarity === 'Unique') Object.assign(it, { rarity: 'Rare', unique: 'None', name: '', affixes: it.affixes.filter(a => !a.id.startsWith('unique:')), roll: undefined });
      } else {
        k.oathwordMode.delete(String(key)); k.oathwordSelection.delete(String(key));
        if (oathwordForItem(it, slot)) it.runes = [];
      }
      return it ? done() : render();
    }
    if (f === 'oathword') {
      const word = oathwordsFor(slot).find(w => lc(w.Id) === lc(v));
      if (!word) { k.oathwordSelection.delete(String(key)); return render(); }
      k.oathwordSelection.set(String(key), word.Id);
      const base = it && oathwordBases(slot, word).find(b => lc(b.Id) === lc(it.base));
      if (base) { it.runes = word.Runes.slice(); it.unique = 'None'; return done(); }
      return render();
    }
    if (f === 'oathbase') {
      const word = (GD.runewords || []).find(w => lc(w.Id) === lc(k.oathwordSelection.get(String(key)) || (oathwordForItem(it, slot) || {}).Id));
      const base = word && oathwordBases(slot, word).find(b => lc(b.Id) === lc(v));
      if (!word || !base) return render();
      if (!it) {
        ch.items.push({ slot, base: base.Id, rarity: 'Rare', unique: 'None', name: '', level: ch.level, affixes: [], runes: word.Runes.slice() });
        k.openItems.add(String(ch.items.length - 1));
        k.oathwordMode.delete(String(key)); k.oathwordSelection.delete(String(key));
      } else {
        it.base = base.Id;
        if (it.rarity === 'Unique') Object.assign(it, { rarity: 'Rare', unique: 'None', name: '', affixes: [], roll: undefined });
        else it.affixes = it.affixes.filter(a => affixesFor(base).some(x => lc(x.Id) === lc(a.id)));
        it.unique = 'None'; it.runes = word.Runes.slice();
      }
      return done();
    }
    if (f === 'base') {
      if (!v) { ch.items = ch.items.filter(i => i !== it); k.openItems.delete(String(key)); return done(); }
      const u = it && GD.uniques[lc(it.unique)];
      if (it) { it.base = v; if (u && lc(u.BaseId) !== lc(v)) { it.rarity = 'Rare'; it.unique = 'None'; it.affixes = []; } it.affixes = it.affixes.filter(a => a.id.startsWith('unique:') || affixesFor(GD.bases[lc(v)]).some(x => lc(x.Id) === lc(a.id))); }
      else { ch.items.push({ slot, base: v, rarity: 'Rare', unique: 'None', name: '', level: ch.level, affixes: [], runes: [] }); k.openItems.add(slot); }
      return done();
    }
    // The "Unique" box: ticking lists the slot's uniques; unticking turns a unique back into a Rare of the same base.
    if (f === 'unique') {
      if (!v) { if (it) { ch.items = ch.items.filter(i => i !== it); k.openItems.delete(String(key)); return done(); } return render(); }
      const u = GD.uniques[lc(v)]; if (!u) return render();
      let item = it;
      if (!item) { item = { slot, base: u.BaseId, rarity: 'Unique', unique: u.Id, name: u.Name, level: ch.level, affixes: [], runes: [] }; ch.items.push(item); k.openItems.add(slot); }
      Object.assign(item, { rarity: 'Unique', unique: u.Id, base: u.BaseId, name: u.Name, runes: [] });
      rollUnique(item, item.roll == null ? 0.5 : item.roll);
      return done();
    }
    if (!it) return;
    const ai = +(t.closest('[data-ai]') || {}).dataset?.ai;
    switch (f) {
      case 'rarity':
        if (v === 'Unique') { it.rarity = 'Unique'; it.unique = 'None'; it.affixes = []; it.runes = []; }
        else { if (it.rarity === 'Unique') { it.affixes = []; it.unique = 'None'; it.name = ''; } it.rarity = v; if (v === 'Normal') it.affixes = []; }
        return done();
      case 'ilvl': it.level = Math.max(1, Math.min(100, +v || 1)); return done();
      case 'addaffix': {
        const af = GD.affixes[lc(v)]; if (!af) return render();
        const ti = topTier(af, it.level || ch.level), tt = af.Tiers[ti];
        it.affixes.push(Object.assign({ id: af.Id, tier: ti, v: tt.Max, v2: tt.Max2 != null ? tt.Max2 : 0 }, t.dataset.x === 'oath' ? { oath: true } : t.dataset.x === 'scar' ? { scar: true } : {})); return done();
      }
      case 'tier': { const a = it.affixes[ai], af = GD.affixes[lc(a.id)], tt = af.Tiers[+v]; Object.assign(a, { tier: +v, v: tt.Max, v2: tt.Max2 != null ? tt.Max2 : 0 }); return done(); }
      case 'v': it.affixes[ai].v = +v || 0; delete it.roll; return done(); // a hand-set unique line: no longer "rolls at N%"
      case 'v2': it.affixes[ai].v2 = +v || 0; delete it.roll; return done();
      case 'rune': { it.runes[+t.dataset.ri] = v; it.runes = Array.from(it.runes, r => r || '').slice(0, runeSlots(GD.bases[lc(it.base)])).filter(Boolean); return done(); } // order matters for runewords: empty sockets close up
    }
  }
  async function onClick(e) {
    const b = e.target.closest('[data-act]'); if (!b) return;
    const act = b.dataset.act;
    if (act === 'importcode') return importCodeBox();
    if (!ctx.current()) return;
    if (act === 'resetlinks') { status = ''; return ctx.resetLinks(); }
    const ch = ctx.editable();
    if (act === 'dnode') {
      const r = dToggle(ch, b.dataset.id);
      if (!r.nodes) { status = r.msg; return render(); }
      ch.dragonNodes = r.nodes; status = ''; return done();
    }
    if (act === 'dreset') { ch.dragonNodes = []; status = 'Dragonling points refunded.'; return done(); }
    const row = b.closest('[data-skill]'), skill = row && row.dataset.skill;
    if (act === 'simbest') {
      if (b.disabled || !skill) return;
      b.disabled = true; b.textContent = 'Searching…';
      const sup = await ctx.bestSupports(skill, p => { b.textContent = 'Searching… ' + p + '%'; });
      const name = (GD.skills[lc(skill)] || {}).Name || skill;
      if (!sup) { status = 'No support setup found for ' + name + '.'; return render(); }
      ensureSocket(ch, skill).supports = sup;
      status = 'Best supports for ' + name + ': ' + (sup.map(id => (GD.supports[lc(id)] || { Name: id }).Name).join(', ') || 'none') + '.';
      return done({ skills: true });
    }
    if (act === 'code' && ch.plan) {
      const code = await toCode(ctx.withTabs(ch));
      try { await navigator.clipboard.writeText(code); status = 'Plan code copied (' + code.length + ' characters). Paste it into the code box at the top to open it here or in another browser.'; }
      catch (err) { window.prompt('Copy this plan code:', code); }
      return render();
    }
    if (act === 'dup' && ch.plan) { const p = planFrom(ch); status = 'Duplicated.'; ctx.add(p, ch); return render(); }
    if (act === 'del' && ch.plan) { if (!window.confirm('Delete the plan "' + ch.name + '"? This cannot be undone (copy its plan code first to keep it).')) return; status = ''; ctx.remove(ch); return render(); }
    if (act === 'rmskill') { removeSkill(ch, skill); return done({ skills: true }); }
    if (act === 'togsup') {
      // Same rules as the Damage tab's picker: one shape support at a time, no more than the sockets allow.
      const id = lc(b.dataset.sup), sd = GD.supports[id] || {}, s = ensureSocket(ch, skill);
      if (s.supports.some(x => lc(x) === id)) { s.supports = s.supports.filter(x => lc(x) !== id); status = ''; return done({ skills: true }); }
      const SHAPES = ['orbit', 'rain_support', 'trap_support', 'totem_support'];
      const swap = SHAPES.includes(id) ? s.supports.find(x => SHAPES.includes(lc(x))) : null;
      const slots = S.socketsFor(GD, ch, skill, ch.gemLevels[skill] || 1);
      if (GD.skills[lc(skill)] && !S.supportChoices(GD, ch, skill, { conduit: s.conduit }).some(c => c.id === id)) { status = (sd.Name || id) + ' cannot go into ' + (GD.skills[lc(skill)].Name) + (S.noFitWhy(sd, GD.skills[lc(skill)]) ? ': ' + S.noFitWhy(sd, GD.skills[lc(skill)]) + '.' : '.'); return render(); }
      if (swap) { s.supports = s.supports.filter(x => x !== swap); status = (sd.Name || id) + ' replaces ' + (GD.supports[lc(swap)] || { Name: swap }).Name + ': only one shape support counts.'; }
      else if (s.supports.length >= slots) { status = 'All ' + slots + ' sockets are used: take a support out first (a higher gem level opens more).'; return render(); }
      else status = '';
      s.supports.push(sd.Id || id);
      return done({ skills: true });
    }
    if (act === 'rmsup') { const s = ch.sockets.find(x => x.skill === skill); if (s) s.supports = s.supports.filter(x => x !== b.dataset.sup); return done({ skills: true }); }
    if (act === 'addidol') {
      const base = basesFor('Idol')[0]; if (!base) return;
      ch.items.push({ slot: 'Idol', base: base.Id, rarity: 'Magic', unique: 'None', name: '', level: ch.level, affixes: [], runes: [] });
      K.openItems.add(String(ch.items.length - 1)); return done();
    }
    gearClick(ch, b, K, done);
  }
  function gearClick(ch, b, k, done) {
    const act = b.dataset.act, { it, key } = itemOf(ch, b);
    if (act === 'rmitem' && it) { ch.items = ch.items.filter(i => i !== it); k.openItems.clear(); return done(); }
    if (act === 'rmaffix' && it) { it.affixes.splice(+b.dataset.ai, 1); k.openItems.add(String(key)); return done(); }
  }
  // Reading an item from a screenshot or its tooltip text (itemread.js) into one gear box of the Build tab.
  // The box's read area takes focus on click, so Ctrl+V there (or anywhere in an open box) reads the clipboard.
  const RD = { key: null, busy: '', r: null };
  function readHtml(key) {
    const busy = RD.key === key && RD.busy;
    let h = '<div class="pl-read" tabindex="0" role="button" data-key="' + esc(key) + '" aria-label="Paste, drop or pick a screenshot of the item">' +
      '<b>' + (busy ? esc(busy) : 'Read a screenshot') + '</b>' +
      (busy ? '' : ' <span>Click here and paste it (Ctrl+V), drop it here, or <label class="linkish">pick an image<input type="file" data-f="readimg" accept="image/*" hidden></label>. Item text works too. The image is read in this browser and never uploaded.</span>') + '</div>';
    const r = RD.key === key && RD.r;
    if (r && r.error) h += '<p class="hint bad">' + esc(r.error) + '</p>';
    else if (r) {
      const cls = { affix: 'good', unique: 'good', unread: 'bad' }, n = r.lines.filter(l => l.kind === 'affix' || l.kind === 'unique').length;
      h += '<details class="cmp-readout"' + (r.unread.length || r.notes.length ? ' open' : '') + '><summary>Read ' + n + ' item line' + (n === 1 ? '' : 's') + (r.unread.length ? ', <span class="bad">' + r.unread.length + ' not recognised</span>' : '') + '. Check them against the screenshot.</summary><ul>' +
        r.lines.map(l => '<li class="' + (cls[l.kind] || 'meta') + '">' + esc(l.text) + (l.label ? ' <span class="meta">· ' + esc(l.label) + '</span>' : l.kind === 'unread' ? ' <span class="meta">· not recognised</span>' : '') + '</li>').join('') + '</ul>' +
        r.notes.map(t => '<p class="hint bad">' + esc(t) + '</p>').join('') +
        (r.unread.length ? '<p class="hint">Add lines that were not recognised with <b>Add an affix</b> below.</p>' : '') + '</details>';
    }
    return h;
  }
  // src is an image (Blob) or item text. The read item replaces what the box holds (in this page only).
  async function readInto(box, src) {
    if (!ctx.current() || RD.busy || !window.BOItemRead) return;
    const key = box.dataset.item;
    K.openItems.add(key); RD.key = key; RD.r = null;
    let text = src;
    if (typeof src !== 'string') {
      RD.busy = 'Loading the text reader…'; render();
      try {
        text = await window.BOItemRead.readImage(src, t => { RD.busy = t; const b = pane().querySelector('.pl-read[data-key="' + key + '"] b'); if (b) b.textContent = t; });
      } catch (err) { RD.busy = ''; RD.r = { error: 'Could not read the screenshot: ' + err.message }; return render(); }
      RD.busy = '';
    }
    const ch = ctx.editable(), { it, slot } = itemOf(ch, box);
    if (!slot) return render();
    const r = window.BOItemRead.parse(GD, S, text, { slot, base: it && it.base, level: ch.level });
    if (!r.item) { RD.r = { error: typeof src === 'string' ? 'That text does not look like an item.' : 'No item text found in that image. Crop it to the tooltip and try again.' }; return render(); }
    const item = Object.assign(r.item, { slot });
    if (/^-?\d+$/.test(key) && ch.items[+key]) ch.items[+key] = item;
    else { ch.items = ch.items.filter(i => i.slot !== slot); ch.items.push(item); }
    for (const m of [K.uniqueMode, K.oathwordMode, K.oathwordSelection]) m.delete(key); // the box follows the read item
    // A filled box is found by the item's index from now on (an empty one by its slot name).
    RD.key = String(ch.items.indexOf(item)); K.openItems.add(RD.key);
    RD.r = r; status = '';
    done();
  }
  function readDrop(target, file) {
    const box = target && target.closest && target.closest('#buildPane [data-item]');
    if (!box || pane().hidden) return false;
    readInto(box, file); return true;
  }
  document.addEventListener('paste', e => {
    const el = pane(); if (!el || el.hidden || !ctx.current()) return;
    if (e.target.closest && e.target.closest('input, textarea, select')) return;
    const a = document.activeElement, box = a && a.closest && a.closest('#buildPane [data-item]');
    if (!box) return;
    const items = Array.from((e.clipboardData && e.clipboardData.items) || []);
    const img = items.find(i => i.kind === 'file' && /^image\//.test(i.type));
    if (img) { e.preventDefault(); return readInto(box, img.getAsFile()); }
    const text = e.clipboardData && e.clipboardData.getData('text/plain');
    if (text && /\n/.test(text.trim()) && /\d/.test(text)) { e.preventDefault(); readInto(box, text); }
  });
  // Remember which item editors are open across re-renders.
  function onToggle(e) {
    const d = e.target; if (d.matches && d.matches('details.pl-setup')) { setupOpen = d.open; return; }
    if (!d.matches || !d.matches('details[data-item]')) return;
    if (d.open) K.openItems.add(d.dataset.item); else K.openItems.delete(d.dataset.item);
  }
  const el = pane();
  el.addEventListener('change', onChange);
  el.addEventListener('click', onClick);
  el.addEventListener('toggle', onToggle, true);
  el.addEventListener('mousedown', e => { const sel = e.target.closest && e.target.closest(PICKER); if (sel && !sel.disabled && e.button === 0) { e.preventDefault(); if (pick && pick.sel === sel) closePicker(); else openPicker(sel); } });
  el.addEventListener('keydown', e => { const sel = e.target.closest && e.target.closest(PICKER); if (sel && !sel.disabled && (e.key === 'Enter' || e.key === ' ' || (e.altKey && e.key === 'ArrowDown'))) { e.preventDefault(); openPicker(sel); } });
  el.addEventListener('input', e => { if (e.target.id === 'plCode') codeDraft = e.target.value; });
  el.addEventListener('keydown', e => { if (e.key === 'Enter' && e.target.id === 'plCode') { e.preventDefault(); importCodeBox(); } });
  el.addEventListener('mousemove', showItemTip);
  el.addEventListener('mouseleave', hideItemTip);
  el.addEventListener('keydown', e => { const r = e.target.closest && e.target.closest('.pl-read'); if (r && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); const i = r.querySelector('input[type=file]'); if (i) i.click(); } });
  el.addEventListener('toggle', hideItemTip, true);

  // Take or refund one Dragonling node: { nodes } (the new list) or { msg } (why not).
  function dToggle(ch, id) {
    const n = dTree(ch)[id]; if (!n) return { msg: 'Unknown node.' };
    const st = dState(ch, id);
    if (st.s === 'open') return { nodes: [...(ch.dragonNodes || []), id] };
    if (st.s === 'taken' && !st.why) return { nodes: ch.dragonNodes.filter(x => x !== id) };
    return { msg: dLabel(ch, n).name + ': ' + (st.why || 'not reachable yet') + '.' };
  }
  // The Dragonling tree for the Skill tree tab (app.js draws it in a panel and handles its clicks).
  // One node's details for a tooltip: its lines are the Ascended ones when it is ascended, and a Capstone's
  // Aspect lines when it is not.
  function dInfo(ch, id) {
    const n = dTree(ch)[id]; if (!n) return null;
    const a = ascOn(ch) && n.Ascend, lab = dLabel(ch, n), st = dState(ch, id);
    let mods = (a ? a.Mods : n.Mods) || [];
    if (!a && n.AspectMods && n.AspectMods[ch.dragonAspect]) mods = mods.concat(n.AspectMods[ch.dragonAspect]);
    const aspect = n.Kind === 'Core' && GD.dragon.aspects && GD.dragon.aspects[ch.dragonAspect];
    return { id, kind: n.Kind, path: n.Path || '', name: lab.name, text: aspect ? (aspect.Name || ch.dragonAspect) + ' Aspect: ' + aspect.Text : lab.text, mods: aspect ? aspect.Mods || [] : mods, state: st.s, why: st.why || '' };
  }
