  // Can one more idol of this shape go in? 'here' = in the free cells now, 'move' = only if others move, '' = no.
  function roomFor(s) {
    if (firstSpot(usedBy(null), s.w, s.h)) return 'here';
    return firstLayout([...F.idols.map(dims), [s.w, s.h]]) ? 'move' : '';
  }

