        const list = its.map(i => ({ base: lc(i.base), label: (u(i) || {}).Name || i.name || '', uniq: u(i) ? lc(i.unique) : '' }));
        const pos = firstLayout(list.map(i => { const s = shape(i.base); return [s.w, s.h]; }));
