      const [w, h] = dims(it), x = +c.dataset.x, y = +c.dataset.y, ok = fitsAt(usedBy(it), x, y, w, h);
      for (const [cx, cy] of cellsOf(x, y, w, h)) { const q = el.querySelector('.fo-cell[data-x="' + cx + '"][data-y="' + cy + '"]'); if (q) q.classList.add(ok ? 'ok' : 'no'); }
