  const read = id => { try { return cleanBelt(JSON.parse(localStorage.getItem(KEY(id)) || 'null')); } catch (e) { return null; } };
  const write = (id, b) => { try { localStorage.setItem(KEY(id), JSON.stringify(b)); } catch (e) { /* storage off */ } };
