    const picks = u ? [] : [...s.pre, ...s.suf, s.oath, s.core].filter(Boolean).map(x => ({ m: modById(x.id), t: (modById(x.id).Tiers || []).find(z => z.Tier === x.tier) })).filter(x => x.m && x.t);
    const byEffect = e => picks.find(x => x.m.Effect === e);
    const firstPre = picks.find(x => x.m.Kind === 'Prefix'), firstSuf = picks.find(x => x.m.Kind === 'Suffix');
    const name = u ? u.Name : [firstPre && firstPre.m.Name, t.Name, firstSuf && firstSuf.m.Name].filter(Boolean).join(' ');
    const lines = [{ text: t.Text, base: true }];
