      if (ext) for (let b = 1; b <= BONUS_ALL; b++) rows += '<tr class="sc-bonus"><td>' + (max + b) + '</td><td>' + atBonus(sk, G, b) + '</td><td>–</td></tr>';
      h += '<details><summary>All levels 1-' + (max + (ext ? BONUS_ALL : 0)) + '</summary><div class="table-wrap"><table class="tbl"><thead><tr><th>Level</th><th>' + (k === 'attack' ? '% weapon' : 'Hit') + '</th><th>Mana</th></tr></thead><tbody>' + rows + '</tbody></table></div></details>';
