    const GD = ctx.gd();
    let h = '<div class="cmp-intro"><div class="eyebrow">REFERENCE</div><h2>Skill Scaling</h2><p>What each skill does as its gem levels up. The colour is the gem\'s: red Strength, green Dexterity, blue Intelligence.</p></div>';
    if (!GD || !GD.skills || !GD.scaling || !GD.scaling.Gem) { el.innerHTML = h + '<div class="card"><p class="hint">Load the game data first.</p></div>'; return; }
    const G = GD.scaling.Gem, max = G.MaxLevel || 20;
