    if (filter !== 'all' && !groups.some(g => GROUP[g.a][0] === filter)) filter = 'all';
    const chips = [['all', 'All']].concat(groups.map(g => [GROUP[g.a][0], GROUP[g.a][0][0].toUpperCase() + GROUP[g.a][0].slice(1)]));
