    if (!tipEl) { tipEl = document.createElement('div'); tipEl.className = 'pl-tip'; tipEl.setAttribute('role', 'tooltip'); document.body.appendChild(tipEl); }
    if (tipEl.dataset.key !== id) { tipEl.innerHTML = html; tipEl.dataset.key = id; }
