              table(['Attack', 'Range', 'Cooldown', 'Damage ×', 'Element'], (mon.Attacks || []).map(a => [esc(a.Kind), a.Range || '', a.Cooldown === undefined ? '' : a.Cooldown + ' s', a.Damage === undefined ? '' : a.Damage, esc(a.Element || '')])) + '</details>';;
