        const STAT = { LifeRegenPct: v => v + '% life regeneration', MinionDamage: v => v + '% more minion damage', ArmourPct: v => v + '% more armour', MinionSpeed: v => v + '% minion speed', EnemyTaken: v => 'enemies take ' + v + '% more damage' };
