    const xs = nodes.map(n => n.X), ys = nodes.map(n => n.Y);
    const pad = 300;
    T.full = [Math.min(...xs) - pad, Math.min(...ys) - pad, Math.max(...xs) - Math.min(...xs) + 2 * pad, Math.max(...ys) - Math.min(...ys) + 2 * pad];
