    GS_LAYERS.map(([k, n]) => '<label class="check-row"><input type="checkbox" data-gs-layer="' + k + '"' + (GS.set.layers[k] ? ' checked' : '') + (off ? ' disabled' : '') + '><span>' + n + '</span></label>').join('');
