    const rel = p.slice(siteRoot().length).toLowerCase().replace(/\/+$/, '').replace(/^zh(\/|$)/, ''); // zh/...: the Chinese pages (src/i18n.js)
    if (rel === 'build/gear') return 'character'; // the old Gear sub-tab: gear is edited on the Character tab now
