    if (tab === 'creator') creator.render();
    if (tab === 'fossil') fossil.render();
    if (tab === 'brewery') brewery.render();
    if (tab === 'items') itemSearch.render();
    if (tab === 'grail') grail.render();
    if (tab === 'ladder') ladder.render();
    if (tab === 'faq') faq.render();
