    if (b.dataset.tab === 'plan') { if (await planner.startNewPlan()) showTab('plan'); }
    else if (b.dataset.tab === 'build' && st.ch) showTab(lastBuildView()); // back to the Build Planner view used last
    else showTab(b.dataset.tab);
