  // Skills from the other Build Planner views goes back to the build pane.
  $('#buildSubtabs').addEventListener('click', e => { if (e.target.closest('[data-sub]') && (document.body.classList.contains('tree-page') || document.body.classList.contains('dashboard-view') || document.body.classList.contains('character-page'))) showTab('build'); });

  // Pan, zoom, hover, click.
  const view = $('#treeView'), tip = $('#treeTip');
  const inDragon = e => e.target.closest && e.target.closest('.dragon-btn, .dragon-panel');
  view.addEventListener('wheel', e => { if (!T.vb || inDragon(e)) return; e.preventDefault(); const [cx, cy] = svgPoint(e); zoomAt(e.deltaY > 0 ? 1.18 : 1 / 1.18, cx, cy); }, { passive: false });
  // Touch: two fingers pinch-zoom (and pan), double-tap on empty space zooms in.
