      const nw = Math.min(T.full[2] * 1.4, Math.max(900, w0 * T.pinch.d / p.d)), nh = h0 * nw / w0;
      setVB([T.pinch.sx - (p.x - r.left) / r.width * nw, T.pinch.sy - (p.y - r.top) / r.height * nh, nw, nh]);
